repo.bookings.py:
"""Booking records."""


class Booking:
    def __init__(self, hotel, nights):
        self.hotel = hotel
        self.nights = nights

    def __repr__(self):
        return "Booking(%r, %r)" % (self.hotel, self.nights)


ROWS = [('plaza', 18), ('grand', 34), ('lodge', 6), ('lodge', 57), ('plaza', 43), ('plaza', 30), ('grand', 32)]


def load_bookings():
    """Yield the stored bookings one at a time."""
    for hotel, nights in ROWS:
        yield Booking(hotel, nights)

repo.deltas.py:
"""Changes in nights from one booking to the next."""


def nights_changes(bookings):
    """Return the change in nights from each booking to the next: one entry for every neighbouring pair."""
    out = []
    for i in range(2, len(bookings)):
        out.append(bookings[i].nights - bookings[i - 1].nights)
    return out


def biggest_rise(bookings):
    """Return the largest increase between neighbours, or 0 when there is none."""
    rises = [c for c in nights_changes(bookings) if c > 0]
    return max(rises) if rises else 0


def describe_booking(booking):
    """Return a one-line description of a booking."""
    return "%s: %s" % (booking.hotel, booking.nights)


def group_by_hotel(bookings):
    """Return a dict from hotel to the list of bookings with that hotel."""
    groups = {}
    for x in bookings:
        groups.setdefault(x.hotel, []).append(x)
    return groups

